* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: #eef2f6;
  color: #111827;
  font-family: Inter, Arial, sans-serif;
}

.page {
  min-height: 100vh;
  padding: 16px;
}

.toolbar {
  display: grid;
  grid-template-columns: minmax(240px, 1.4fr) minmax(150px, 0.8fr) 140px 140px 108px 96px;
  gap: 10px;
  align-items: end;
  background: #ffffff;
  border: 1px solid #d8dee8;
  border-radius: 8px;
  padding: 12px;
  margin-bottom: 12px;
}

.control label {
  display: block;
  margin-bottom: 5px;
  color: #667085;
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
}

.control select,
.control input {
  width: 100%;
  height: 38px;
  border: 1px solid #cfd7e3;
  border-radius: 7px;
  padding: 0 10px;
  background: #ffffff;
  color: #111827;
  font-size: 13px;
  outline: none;
}

.control select:disabled {
  background: #f2f4f7;
  color: #667085;
}

.is-hidden {
  display: none;
}

.btn {
  height: 38px;
  border: 0;
  border-radius: 7px;
  background: #dff7e8;
  color: #14532d;
  font-weight: 900;
  cursor: pointer;
}

.btn-dark {
  background: #111827;
  color: #ffffff;
}

.header {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  background: #111827;
  color: #ffffff;
  border-radius: 8px;
  padding: 18px;
  margin-bottom: 12px;
}

.eyebrow {
  color: #8ce6c3;
  font-size: 12px;
  font-weight: 900;
  text-transform: uppercase;
}

.header h1 {
  margin: 4px 0 4px;
  font-size: 24px;
  line-height: 1.15;
}

.header p {
  margin: 0;
  color: #d1d5db;
  font-size: 12px;
}

.stamp {
  min-width: 190px;
  text-align: right;
  color: #d1d5db;
  font-size: 12px;
}

.stamp strong {
  display: block;
  margin-top: 4px;
  color: #ffffff;
}

.stamp small {
  display: block;
  margin-top: 4px;
}

.kpis {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 10px;
  margin-bottom: 12px;
}

.kpi {
  background: #ffffff;
  border: 1px solid #d8dee8;
  border-radius: 8px;
  padding: 13px;
  min-height: 104px;
}

.kpi-label {
  color: #667085;
  font-size: 11px;
  font-weight: 900;
  text-transform: uppercase;
}

.kpi-value {
  margin-top: 8px;
  color: #111827;
  font-size: 22px;
  font-weight: 900;
  line-height: 1.1;
}

.kpi-hint {
  margin-top: 8px;
  color: #667085;
  font-size: 11px;
}

.kpi-green {
  border-top: 4px solid #0f766e;
}

.kpi-blue {
  border-top: 4px solid #2563eb;
}

.kpi-amber {
  border-top: 4px solid #b45309;
}

.kpi-red {
  border-top: 4px solid #b91c1c;
}

.kpi-muted {
  border-top: 4px solid #475467;
}

.grid {
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(360px, 0.8fr);
  gap: 12px;
}

.card {
  background: #ffffff;
  border: 1px solid #d8dee8;
  border-radius: 8px;
  padding: 14px;
  min-height: 250px;
}

.card-wide {
  grid-column: span 2;
}

.card-head {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 12px;
  padding-bottom: 10px;
  margin-bottom: 8px;
  border-bottom: 1px solid #e7ecf2;
}

.card-head h2 {
  margin: 0;
  font-size: 15px;
  line-height: 1.2;
}

.card-head span {
  color: #667085;
  font-size: 11px;
  font-weight: 800;
}

.status-grid {
  display: grid;
  gap: 10px;
}

.status-grid div {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border: 1px solid #e7ecf2;
  border-radius: 7px;
  padding: 11px;
  background: #f8fafc;
}

.status-grid span {
  color: #667085;
  font-size: 12px;
}

.status-grid b {
  font-size: 18px;
}

.list-row,
.movement-row {
  display: flex;
  justify-content: space-between;
  gap: 14px;
  padding: 10px 0;
  border-bottom: 1px solid #edf1f5;
}

.list-row:last-child,
.movement-row:last-child {
  border-bottom: 0;
}

.row-main strong,
.movement-row strong {
  display: block;
  color: #111827;
  font-size: 12px;
}

.row-main span,
.movement-row span {
  display: block;
  margin-top: 3px;
  color: #667085;
  font-size: 11px;
}

.row-value {
  min-width: 92px;
  text-align: right;
  white-space: nowrap;
  font-size: 12px;
}

.row-value b {
  display: block;
}

.row-value small {
  display: block;
  margin-top: 5px;
  color: #667085;
}

.alert-bad {
  border-left: 4px solid #b91c1c;
  padding-left: 10px;
}

.alert-warn {
  border-left: 4px solid #b45309;
  padding-left: 10px;
}

.badge {
  display: inline-block;
  padding: 4px 7px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 900;
  text-transform: uppercase;
}

.badge-good {
  background: #dcfce7;
  color: #166534;
}

.badge-warn {
  background: #fef3c7;
  color: #92400e;
}

.badge-bad {
  background: #fee2e2;
  color: #991b1b;
}

.badge-muted {
  background: #e5e7eb;
  color: #374151;
}

.positive {
  color: #047857;
}

.negative {
  color: #b91c1c;
}

.empty {
  padding: 26px 12px;
  border: 1px dashed #cbd5e1;
  border-radius: 8px;
  background: #f8fafc;
  color: #667085;
  text-align: center;
  font-size: 12px;
}

.trend {
  display: grid;
  gap: 9px;
}

.trend-row {
  display: grid;
  grid-template-columns: 88px 1fr 70px;
  gap: 10px;
  align-items: center;
  font-size: 11px;
}

.trend-track {
  height: 12px;
  background: #e5e7eb;
  border-radius: 999px;
  overflow: hidden;
}

.trend-fill {
  height: 100%;
  background: #0f766e;
}

.trend-row b {
  text-align: right;
}

@media (max-width: 1180px) {
  .toolbar {
    grid-template-columns: 1fr 1fr 1fr;
  }
  .kpis {
    grid-template-columns: repeat(3, 1fr);
  }
  .grid {
    grid-template-columns: 1fr;
  }
  .card-wide {
    grid-column: span 1;
  }
}
@media (max-width: 760px) {
  .page {
    padding: 10px;
  }
  .toolbar,
  .kpis {
    grid-template-columns: 1fr;
  }
  .header {
    flex-direction: column;
  }
  .stamp {
    text-align: left;
  }
  .trend-row {
    grid-template-columns: 76px 1fr 56px;
  }
}
@media print {
  body {
    background: #ffffff;
  }
  .no-print,
  .toolbar {
    display: none !important;
  }
  .page {
    padding: 0;
    background: #ffffff;
  }
  .header {
    background: #ffffff;
    color: #111827;
    border: 1px solid #111827;
  }
  .header p,
  .stamp,
  .stamp strong {
    color: #111827;
  }
  .eyebrow {
    color: #111827;
  }
  .card,
  .kpi {
    break-inside: avoid;
  }
}

