function money(value) {
  return Number(value || 0).toLocaleString("en-GB", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  });
}

function qty(value) {
  return Number(value || 0).toLocaleString("en-GB", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  });
}

function safe(value, fallback = "-") {
  return value === null || value === undefined || value === "" ? fallback : String(value);
}

function model() {
  return window.appsmith?.model || {};
}

function controls() {
  const m = model();

  return {
    warehouseId: Number(m.controls?.warehouseId ?? m.warehouseId ?? 0),
    period: m.controls?.period || "30D",
    dateFrom: m.controls?.dateFrom || "",
    dateTo: m.controls?.dateTo || ""
  };
}

async function sendControls(next = {}) {
  const m = model();
  const nextControls = {
    ...controls(),
    ...next
  };

  if (window.appsmith?.updateModel) {
    await window.appsmith.updateModel({
      ...m,
      controls: nextControls
    });
  }

  if (window.appsmith?.triggerEvent) {
    window.appsmith.triggerEvent("onInventoryAnalyticsChange");
  }
}

function tone(value) {
  const v = String(value || "").toUpperCase();

  if (["DONE", "POSTED", "RECEIVED", "OK", "PACKED"].includes(v)) return "good";
  if (["OPEN", "LOW_STOCK", "REQUESTED", "IN_PROGRESS", "PICKING", "PACKING", "SHIPPED"].includes(v)) return "warn";
  if (["OUT_OF_STOCK", "MISSING", "DAMAGED", "CANCELLED"].includes(v)) return "bad";

  return "muted";
}

function kpi(label, value, hint, variant = "muted") {
  return `
    <article class="kpi kpi-${variant}">
      <div class="kpi-label">${label}</div>
      <div class="kpi-value">${value}</div>
      <div class="kpi-hint">${hint || ""}</div>
    </article>
  `;
}

function empty(label) {
  return `<div class="empty">${label}</div>`;
}

function renderWarehouseOptions(m) {
  const selected = Number(controls().warehouseId || 0);
  const warehouses = m.warehouses || [];

  if (!warehouses.length) {
    return `<option value="${selected}">${safe(m.warehouseName, "Selected Warehouse")}</option>`;
  }

  return warehouses.map(w => `
    <option value="${w.value}" ${Number(w.value) === selected ? "selected" : ""}>
      ${safe(w.label || w.name)}
    </option>
  `).join("");
}

function renderToolbar(m) {
  const c = controls();
  const showCustom = c.period === "CUSTOM";

  return `
    <section class="toolbar no-print">
      <div class="control control-wide">
        <label>Warehouse</label>
        <select id="warehouseSelect" ${m.canViewAllWarehouses ? "" : "disabled"}>
          ${renderWarehouseOptions(m)}
        </select>
      </div>

      <div class="control">
        <label>Period</label>
        <select id="periodSelect">
          <option value="TODAY" ${c.period === "TODAY" ? "selected" : ""}>Today</option>
          <option value="7D" ${c.period === "7D" ? "selected" : ""}>Last 7 days</option>
          <option value="30D" ${c.period === "30D" ? "selected" : ""}>Last 30 days</option>
          <option value="MONTH" ${c.period === "MONTH" ? "selected" : ""}>This month</option>
          <option value="CUSTOM" ${c.period === "CUSTOM" ? "selected" : ""}>Custom</option>
        </select>
      </div>

      <div class="control ${showCustom ? "" : "is-hidden"}">
        <label>From</label>
        <input id="dateFromInput" type="date" value="${safe(c.dateFrom, "")}">
      </div>

      <div class="control ${showCustom ? "" : "is-hidden"}">
        <label>To</label>
        <input id="dateToInput" type="date" value="${safe(c.dateTo, "")}">
      </div>

      <button id="refreshButton" class="btn">Refresh</button>
      <button id="printButton" class="btn btn-dark">Print</button>
    </section>
  `;
}

function renderAlerts(rows = []) {
  if (!rows.length) return empty("No stock alerts");

  return rows.slice(0, 10).map(r => `
    <div class="list-row alert-${tone(r.alertType)}">
      <div class="row-main">
        <strong>${safe(r.productCode)} - ${safe(r.productName)}</strong>
        <span>${safe(r.alertText)}</span>
      </div>
      <div class="row-value">${qty(r.quantityOnHand)}</div>
    </div>
  `).join("");
}

function renderTopStock(rows = []) {
  if (!rows.length) return empty("No stock value data");

  return rows.slice(0, 10).map(r => `
    <div class="list-row">
      <div class="row-main">
        <strong>${safe(r.productCode)}</strong>
        <span>${safe(r.productName)}</span>
      </div>
      <div class="row-value">
        <b>${money(r.stockValue)}</b>
        <small>Qty ${qty(r.quantityOnHand)}</small>
      </div>
    </div>
  `).join("");
}

function renderTransfers(rows = []) {
  if (!rows.length) return empty("No open transfers");

  return rows.slice(0, 8).map(r => `
    <div class="list-row">
      <div class="row-main">
        <strong>${safe(r.documentNumber)}</strong>
        <span>${safe(r.sourceWarehouseCode)} → ${safe(r.destinationWarehouseCode)}</span>
      </div>
      <div class="row-value">
        <span class="badge badge-${tone(r.status)}">${safe(r.status)}</span>
        <small>${qty(r.totalQuantity)} pcs</small>
      </div>
    </div>
  `).join("");
}

function renderPackages(rows = []) {
  if (!rows.length) return empty("No open packages");

  return rows.slice(0, 8).map(r => `
    <div class="list-row">
      <div class="row-main">
        <strong>${safe(r.packageNumber)}</strong>
        <span>${safe(r.sourceWarehouseCode)} → ${safe(r.destinationWarehouseCode)}</span>
      </div>
      <div class="row-value">
        <span class="badge badge-${tone(r.packageStatus)}">${safe(r.packageStatus)}</span>
        <small>${qty(r.totalQuantity)} pcs</small>
      </div>
    </div>
  `).join("");
}

function renderBreakdown(rows = []) {
  if (!rows.length) return empty("No warehouse breakdown");

  return rows.slice(0, 8).map(r => `
    <div class="list-row">
      <div class="row-main">
        <strong>${safe(r.warehouseCode)} - ${safe(r.warehouseName)}</strong>
        <span>${qty(r.totalQuantity)} units / ${safe(r.productCount, 0)} products</span>
      </div>
      <div class="row-value">
        <b>${money(r.stockValue)}</b>
        <small>${safe(r.lowStockCount, 0)} low / ${safe(r.outOfStockCount, 0)} out</small>
      </div>
    </div>
  `).join("");
}

function renderMovements(rows = []) {
  if (!rows.length) return empty("No recent movements");

  return rows.slice(0, 14).map(r => {
    const negative = Number(r.quantity || 0) < 0;

    return `
      <div class="movement-row">
        <div>
          <strong>${safe(r.productCode)} - ${safe(r.productName)}</strong>
          <span>${safe(r.movementDateText)} / ${safe(r.movementType)} / ${safe(r.documentNumber)} / ${safe(r.warehouseCode)}</span>
        </div>
        <b class="${negative ? "negative" : "positive"}">${qty(r.quantity)}</b>
      </div>
    `;
  }).join("");
}

function renderTrend(rows = []) {
  const grouped = {};

  rows.forEach(r => {
    const key = r.movementDateText || "N/A";
    grouped[key] = (grouped[key] || 0) + Math.abs(Number(r.quantity || 0));
  });

  const points = Object.entries(grouped).slice(0, 12).reverse();
  const max = Math.max(...points.map(p => p[1]), 1);

  if (!points.length) return empty("No movement trend");

  return `
    <div class="trend">
      ${points.map(([label, value]) => `
        <div class="trend-row">
          <span>${label}</span>
          <div class="trend-track">
            <div class="trend-fill" style="width:${Math.max(5, value / max * 100)}%"></div>
          </div>
          <b>${qty(value)}</b>
        </div>
      `).join("")}
    </div>
  `;
}

function attachEvents() {
  const warehouseSelect = document.getElementById("warehouseSelect");
  const periodSelect = document.getElementById("periodSelect");
  const dateFromInput = document.getElementById("dateFromInput");
  const dateToInput = document.getElementById("dateToInput");
  const refreshButton = document.getElementById("refreshButton");
  const printButton = document.getElementById("printButton");

  if (warehouseSelect) {
    warehouseSelect.onchange = () => sendControls({ warehouseId: Number(warehouseSelect.value) });
  }

  if (periodSelect) {
    periodSelect.onchange = () => sendControls({ period: periodSelect.value });
  }

  if (dateFromInput) {
    dateFromInput.onchange = () => sendControls({ period: "CUSTOM", dateFrom: dateFromInput.value });
  }

  if (dateToInput) {
    dateToInput.onchange = () => sendControls({ period: "CUSTOM", dateTo: dateToInput.value });
  }

  if (refreshButton) {
    refreshButton.onclick = () => sendControls({});
  }

  if (printButton) {
    printButton.onclick = () => window.print();
  }
}

function render(m = {}) {
  const overview = m.overview || {};
  const alerts = m.alerts || [];
  const movements = m.movements || [];
  const transfers = m.transfers || [];
  const packages = m.packages || [];
  const topStock = m.topStock || [];
  const breakdown = m.warehouseBreakdown || [];

  const root = document.getElementById("inventory-analytics-root");
  if (!root) return;

  root.innerHTML = `
    <main class="page">
      ${renderToolbar(m)}

      <section class="header">
        <div>
          <div class="eyebrow">Inventory Analytics</div>
          <h1>${safe(m.warehouseName, "Selected Warehouse")}</h1>
          <p>${safe(m.controls?.dateFrom)} - ${safe(m.controls?.dateTo)}</p>
        </div>
        <div class="stamp">
          <span>Generated</span>
          <strong>${safe(m.generatedAt)}</strong>
          <small>${safe(m.generatedBy, "")}</small>
        </div>
      </section>

      <section class="kpis">
        ${kpi("Stock Value", money(overview.stockValue), "Current stock value", "green")}
        ${kpi("Products In Stock", qty(overview.productsInStock), "Products with quantity", "blue")}
        ${kpi("Low Stock", safe(overview.lowStockCount, 0), "Quantity 1-5", Number(overview.lowStockCount || 0) > 0 ? "amber" : "green")}
        ${kpi("Out Of Stock", safe(overview.outOfStockCount, 0), "Quantity zero or below", Number(overview.outOfStockCount || 0) > 0 ? "red" : "green")}
        ${kpi("Period In", qty(overview.periodInQuantity), "Incoming quantity", "green")}
        ${kpi("Period Out", qty(overview.periodOutQuantity), "Outgoing quantity", "amber")}
      </section>

      <section class="grid">
        <article class="card card-wide">
          <div class="card-head">
            <h2>Movement Trend</h2>
            <span>${safe(m.controls?.period)}</span>
          </div>
          ${renderTrend(movements)}
        </article>

        <article class="card">
          <div class="card-head">
            <h2>Operational Status</h2>
            <span>${qty(overview.totalQuantity)} units</span>
          </div>
          <div class="status-grid">
            <div><span>Open transfers</span><b>${safe(overview.openTransfers, 0)}</b></div>
            <div><span>Open tasks</span><b>${safe(overview.openTasks, 0)}</b></div>
            <div><span>Open packages</span><b>${safe(overview.openPackages, 0)}</b></div>
          </div>
        </article>

        <article class="card">
          <div class="card-head">
            <h2>Stock Alerts</h2>
            <span>${alerts.length} rows</span>
          </div>
          ${renderAlerts(alerts)}
        </article>

        <article class="card">
          <div class="card-head">
            <h2>Top Stock Value</h2>
            <span>Top 20</span>
          </div>
          ${renderTopStock(topStock)}
        </article>

        <article class="card">
          <div class="card-head">
            <h2>Open Transfers</h2>
            <span>${transfers.length} docs</span>
          </div>
          ${renderTransfers(transfers)}
        </article>

        <article class="card">
          <div class="card-head">
            <h2>Open Packages</h2>
            <span>${packages.length} packages</span>
          </div>
          ${renderPackages(packages)}
        </article>

        <article class="card">
          <div class="card-head">
            <h2>Warehouse Breakdown</h2>
            <span>${breakdown.length} warehouses</span>
          </div>
          ${renderBreakdown(breakdown)}
        </article>

        <article class="card card-wide">
          <div class="card-head">
            <h2>Recent Movements</h2>
            <span>${movements.length} movements</span>
          </div>
          ${renderMovements(movements)}
        </article>
      </section>
    </main>
  `;

  attachEvents();
}

function update(nextModel) {
  render(nextModel || {});
}

if (window.appsmith?.onReady) {
  window.appsmith.onReady(() => {
    render(window.appsmith.model || {});
    window.appsmith.onModelChange(update);
  });
} else {
  render(model());
}
